import type {
  BreadcrumbsItemProps,
  BreadcrumbsProps,
  BreadcrumbsDropdownIconButtonProps,
  DividerProps,
  EllipsisProps,
} from "./breadcrumbs.types";

import React, { forwardRef, useRef, useMemo, useImperativeHandle } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { PolymorphicRef } from "@types";
import { VerticalScroll } from "@exp-textura/icons";

import { LinkButton } from "../link-button";
import { IconButton } from "../icon-button";
import { Menu } from "../menu";

import { BreadcrumbsClasses, StyledBreadcrumbs } from "./breadcrumbs.styles";
import { BreadcrumbsContext, useBreadcrumbs } from "./hooks/use-breadcrumbs";
import { useOverflowBreadcrumbs } from "./hooks/use-overflow-breadcrumbs";

const Item = forwardRef(function BreadcrumbsItem<C extends React.ElementType = "a">(
  {
    as,
    children,
    disabled,
    value,
    isCurrent,
    className,
    onClick,
    ...props
  }: BreadcrumbsItemProps<C>,
  ref: PolymorphicRef,
) {
  const { disabled: allDisabled, onAction } = useBreadcrumbs();
  const isDisabled = disabled || allDisabled;

  const handleClick = (e: React.MouseEvent<HTMLAnchorElement | HTMLButtonElement>) => {
    if (value !== undefined) {
      onAction?.(value);
    }
    onClick?.(e);
  };

  // If isCurrent is true, render as plain text
  if (isCurrent) {
    return (
      <span
        ref={ref}
        aria-current="page"
        aria-disabled={isDisabled || undefined}
        className={clsx(BreadcrumbsClasses.item, className)}
        data-current={isCurrent}
        {...props}
      >
        {children}
      </span>
    );
  }

  return (
    <LinkButton
      ref={ref}
      as={as || "a"}
      className={clsx(BreadcrumbsClasses.item, className)}
      data-current={isCurrent}
      disabled={isDisabled}
      size="sm"
      tabIndex={isDisabled ? -1 : 0}
      variant="secondary"
      onClick={!isDisabled ? handleClick : undefined}
      {...props}
    >
      {children}
    </LinkButton>
  );
});
Item.displayName = "Breadcrumbs.Item";

const Divider = ({ children, className, ...props }: DividerProps) => {
  const { disabled: allDisabled } = useBreadcrumbs();
  return (
    <span
      aria-hidden="true"
      className={clsx(BreadcrumbsClasses.divider, className)}
      data-disabled={allDisabled}
      role="presentation"
      {...props}
    >
      {children ?? "/"}
    </span>
  );
};
Divider.displayName = "Breadcrumbs.Divider";

const Ellipsis = ({ children, className, ...props }: EllipsisProps) => {
  const { disabled: allDisabled } = useBreadcrumbs();
  return (
    <span
      aria-hidden="true"
      className={clsx(BreadcrumbsClasses.ellipsis, className)}
      data-disabled={allDisabled}
      data-ellipsis="true"
      role="presentation"
      {...props}
    >
      {children ?? "..."}
    </span>
  );
};
Ellipsis.displayName = "Breadcrumbs.Ellipsis";

const DropdownIconButton = forwardRef<HTMLButtonElement, BreadcrumbsDropdownIconButtonProps>(
  (
    {
      className,
      size = "sm",
      buttonType = "secondary",
      disabled,
      value,
      onClick,
      children,
      ...props
    },
    ref,
  ) => {
    const { disabled: allDisabled, onAction } = useBreadcrumbs();
    const isDisabled = disabled || allDisabled;

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      if (value !== undefined) {
        onAction?.(value);
      }
      onClick?.(e);
    };

    return (
      <IconButton
        ref={ref}
        buttonType={buttonType}
        className={clsx(BreadcrumbsClasses.item, BreadcrumbsClasses.dropdownIconButton, className)}
        disabled={isDisabled}
        size={size}
        tabIndex={isDisabled ? -1 : 0}
        onClick={!isDisabled ? handleClick : undefined}
        {...props}
      >
        {children ?? <VerticalScroll />}
      </IconButton>
    );
  },
);
DropdownIconButton.displayName = "Breadcrumbs.DropdownIconButton";

// Type guards for accurate composition
const isDivider = (child: React.ReactNode): boolean =>
  React.isValidElement(child) && child.type === Divider;

const isEllipsis = (child: React.ReactNode): boolean =>
  React.isValidElement(child) && child.type === Ellipsis;

const isBreadcrumbsItem = (
  child: React.ReactNode,
): child is React.ReactElement<BreadcrumbsItemProps<React.ElementType>> =>
  React.isValidElement(child) && child.type === Item;

const applyImplicitCurrent = (childrenArray: React.ReactNode[]): React.ReactNode[] => {
  const hasExplicitCurrent = childrenArray.some(
    (child) => isBreadcrumbsItem(child) && child.props.isCurrent,
  );
  if (hasExplicitCurrent) return childrenArray;

  const lastIndex = childrenArray.length - 1;
  return childrenArray.map((child, index) => {
    if (index === lastIndex && isBreadcrumbsItem(child)) {
      return React.cloneElement(child, { isCurrent: true });
    }
    return child;
  });
};

const BreadcrumbsRoot = forwardRef<HTMLElement, BreadcrumbsProps>(
  (
    {
      className,
      variant = "default",
      onAction,
      disabled,
      children,
      ariaLabel = "Breadcrumb",
      autoOverflow,
      overflowMenuAriaLabel = "More pages",
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(BreadcrumbsClasses.root, className);
    const rootRef = useRef<HTMLDivElement>(null);
    const listRef = useRef<HTMLOListElement>(null);
    const overflowButtonRef = useRef<HTMLLIElement>(null);

    useImperativeHandle(ref, () => rootRef.current as HTMLElement);

    // Normalize children to an array for predictable processing
    const childrenArray = React.Children.toArray(children);

    // Ensure a single current item (implicit if none provided)
    const processedChildren = applyImplicitCurrent(childrenArray);

    const items = useMemo(() => {
      if (!autoOverflow) return [];
      return childrenArray.filter(isBreadcrumbsItem);
    }, [childrenArray, autoOverflow]);

    const { visibleMiddleCount } = useOverflowBreadcrumbs(
      listRef,
      overflowButtonRef,
      items.length > 2 ? items.length - 2 : 0,
      autoOverflow || "gradual",
      rootRef,
    );

    const renderList = (nodes: React.ReactNode[]) => {
      return nodes.map((child, idx) => {
        const isDecorative = isDivider(child) || isEllipsis(child);
        return (
          <li
            key={idx}
            aria-hidden={isDecorative ? "true" : undefined}
            className={BreadcrumbsClasses.listItem}
            role={isDecorative ? "presentation" : undefined}
          >
            {child}
          </li>
        );
      });
    };

    const renderAutoOverflowList = () => {
      const first = items[0];
      const last = items.length > 1 ? items[items.length - 1] : null;
      const middle = items.slice(1, -1);

      const isCollapsed = visibleMiddleCount !== Infinity;
      const overflowMiddle = isCollapsed ? middle.slice(visibleMiddleCount) : [];
      const hasOverflow = overflowMiddle.length > 0;

      return (
        <>
          {/* First Item */}
          <li key="first" className={BreadcrumbsClasses.listItem} data-breadcrumb-index="first">
            {first}
          </li>

          {/* Divider after first */}
          {items.length > 1 && (
            <li
              key="div-first"
              className={BreadcrumbsClasses.listItem}
              data-breadcrumb-divider="true"
            >
              <Divider />
            </li>
          )}

          {/* Middle Items */}
          {middle.map((item, idx) => {
            const isVisible = idx < visibleMiddleCount;
            return (
              <React.Fragment key={`middle-${idx}`}>
                <li
                  aria-hidden={!isVisible ? "true" : undefined}
                  className={BreadcrumbsClasses.listItem}
                  data-breadcrumb-hidden={!isVisible ? "true" : undefined}
                  data-breadcrumb-index={idx + 1}
                >
                  {item}
                </li>
                <li
                  aria-hidden={!isVisible ? "true" : undefined}
                  className={BreadcrumbsClasses.listItem}
                  data-breadcrumb-divider="true"
                  data-breadcrumb-hidden={!isVisible ? "true" : undefined}
                >
                  <Divider />
                </li>
              </React.Fragment>
            );
          })}

          {/* Overflow Menu */}
          <li
            ref={overflowButtonRef}
            aria-hidden={!hasOverflow ? "true" : undefined}
            className={clsx(BreadcrumbsClasses.listItem, BreadcrumbsClasses.overflowItem)}
            data-breadcrumb-hidden={!hasOverflow ? "true" : undefined}
          >
            <Ellipsis />
            <Menu>
              <Menu.Trigger>
                <DropdownIconButton aria-label={overflowMenuAriaLabel} />
              </Menu.Trigger>
              <Menu.Content>
                {overflowMiddle.map((item, idx) => {
                  const { children, value, disabled, onClick, ...restProps } = item.props;
                  const isInteractive = Object.keys(restProps).length > 0;
                  const handleSelect = (e: Event | React.SyntheticEvent<HTMLElement>) => {
                    if (value !== undefined) {
                      onAction?.(value);
                    }
                    onClick?.(e);
                  };

                  return (
                    <Menu.Item
                      key={idx}
                      asChild={isInteractive}
                      disabled={disabled}
                      onSelect={handleSelect}
                    >
                      {isInteractive ? (
                        React.createElement(restProps.as || "a", restProps, children)
                      ) : (
                        <span>{children}</span>
                      )}
                    </Menu.Item>
                  );
                })}
              </Menu.Content>
            </Menu>
          </li>

          {/* Divider before last - only if hasOverflow */}
          {hasOverflow && (
            <li
              key="div-overflow"
              className={BreadcrumbsClasses.listItem}
              data-breadcrumb-divider="true"
            >
              <Divider />
            </li>
          )}

          {/* Last Item */}
          {last && (
            <li key="last" className={BreadcrumbsClasses.listItem} data-breadcrumb-index="last">
              {React.cloneElement(last, { isCurrent: true })}
            </li>
          )}
        </>
      );
    };

    return (
      <BreadcrumbsContext.Provider value={{ disabled, onAction }}>
        <StyledBreadcrumbs
          ref={rootRef}
          aria-label={ariaLabel}
          as="nav"
          autoOverflow={autoOverflow}
          className={rootClasses}
          currentTheme={theme}
          variant={variant}
          {...props}
        >
          <ol ref={listRef} className={BreadcrumbsClasses.list}>
            {autoOverflow ? renderAutoOverflowList() : renderList(processedChildren)}
          </ol>
        </StyledBreadcrumbs>
      </BreadcrumbsContext.Provider>
    );
  },
);
BreadcrumbsRoot.displayName = "Breadcrumbs";

const Breadcrumbs = Object.assign(BreadcrumbsRoot, {
  Item,
  DropdownIconButton,
  Divider,
  Ellipsis,
});

export default Breadcrumbs;
